{#- Farmer Bill on the pre-printed "ऊस हिशोब पावती" pad (A4 portrait, 210 x 297 mm): only values are printed.

    CALIBRATION. Every position is in mm from the top-left corner of the sheet.
      dx / dy  move the whole print (+ = right / down); use them first when everything is off by the same amount.
      pos      [x, y] of each single value: x is where the text starts, y is the middle of the text line.
      col      x where each table column starts; "amount_right" is the right edge all amounts line up against.
      rows     y of the first table row, the gap between rows, and the y of the last row that still fits above the totals.
-#}
{%- set dx = 0 -%}
{%- set dy = 0 -%}
{%- set pos = {
	"bill_no":        [71, 40],
	"farmer_name":    [64, 47],
	"farmer_no":      [71, 55],
	"bill_date":      [138, 39],
	"period":         [132, 47],
	"village":        [132, 55],

	"total_tonnage":  [124, 137],
	"gross_amount_y": 136,
	"binding_kg":     [124, 143],
	"binding_amount_y": 143,
	"other_amount_y": 150,
	"net_amount_y":   159,

	"slip_village":   [151, 212],
	"slip_bill_no":   [151, 222],
	"slip_bill_date": [178, 222],
	"slip_farmer":    [66, 220],
	"slip_amount":    [65, 231],
	"slip_cash_ref":  [50, 238]
} -%}
{%- set col = {"date": 35, "vehicle": 67, "slip": 96, "tonnage": 124, "rate": 140, "amount_right": 190} -%}
{%- set rows = {"first_y": 89, "step": 5, "last_y": 129} -%}

{%- set fd = "dd/MM/yyyy" -%}
{%- set t = namespace(routes=[], gross_qty=0, gross_amt=0, binding_kg=0, binding_amt=0) -%}
{%- for s in doc.slips -%}
 {%- set route = s.route or frappe.db.get_value("Weighment Slip", s.slip, "route") -%}
 {%- if route and route not in t.routes -%}{%- set t.routes = t.routes + [route] -%}{%- endif -%}
 {%- set gross = s.gross_quantity or ((s.cane_weight or 0) / 1000) -%}
 {%- set t.gross_qty = t.gross_qty + gross -%}
 {%- set t.gross_amt = t.gross_amt + (gross * (s.rate or 0))|round(2) -%}
 {%- set t.binding_kg = t.binding_kg + (s.mat_weight or 0) -%}
 {%- set t.binding_amt = t.binding_amt + ((s.mat_weight or 0) / 1000 * (s.rate or 0))|round(2) -%}
{%- endfor -%}
{#- what is left after binding is the other deduction, so the lines always add up to the bill amount -#}
{%- set other_amt = (t.gross_amt - t.binding_amt - ((doc.total_amount or 0) - (doc.round_off or 0)))|round(2) -%}
{%- set village = (doc.village_name or doc.village or "") ~ ((" ( " ~ t.routes|join(", ") ~ " )") if t.routes else "") -%}

{#- more rows than the pad has lines for: the rows move closer together and the text gets smaller -#}
{%- set n = doc.slips|length -%}
{%- set room = rows.last_y - rows.first_y -%}
{%- set step = rows.step if (n - 1) * rows.step <= room else room / (n - 1) -%}
{%- set row_pt = 9.5 if step >= 4.2 else (8 if step >= 3.3 else 6.5) -%}

{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, precision=2) }}{%- endmacro -%}
{%- macro day(d) -%}{{ frappe.utils.formatdate(d, fd) if d else "" }}{%- endmacro -%}
{%- macro put(xy, text, cls="") -%}
<div class="a {{ cls }}" style="left:{{ xy[0] }}mm; top:{{ xy[1] }}mm">{{ text }}</div>
{%- endmacro -%}
{%- macro amount(y, text, cls="") -%}
<div class="a r {{ cls }}" style="left:{{ col.amount_right - 40 }}mm; top:{{ y }}mm; width:40mm">{{ text }}</div>
{%- endmacro -%}
<script>document.title = "{{ doc.name }}";</script>
<style>
@font-face { font-family: "SlipDeva"; font-weight: normal; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Regular.ttf") format("truetype"); }
@font-face { font-family: "SlipDeva"; font-weight: bold; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Bold.ttf") format("truetype"); }
.print-format { page-size: A4; orientation: Portrait; margin: 0mm; padding: 0; max-width: none; }
@page { size: A4 portrait; margin: 0; }
@media print { html, body { margin: 0 !important; padding: 0 !important; } }
/* 1 mm short of the sheet on each side so a rounding error never spills onto a second page */
.fbpad { position: relative; width: 209mm; height: 296mm; overflow: hidden; }
.fbpad .in { position: absolute; left: {{ dx }}mm; top: {{ dy }}mm; width: 210mm; height: 297mm; }
.fbpad, .fbpad div { font-family: "SlipDeva", "Noto Sans Devanagari", sans-serif; color: #000; }
/* y is the middle of the line: the box is 5 mm tall and pulled up by half of that */
.fbpad .a { position: absolute; white-space: nowrap; font-size: 10pt; line-height: 5mm; height: 5mm; margin-top: -2.5mm; }
.fbpad .b { font-weight: bold; }
.fbpad .r { text-align: right; }
.fbpad .row { font-size: {{ row_pt }}pt; }
.fbpad .net { font-size: 11.5pt; font-weight: bold; }
</style>
<div class="fbpad"><div class="in">
{{ put(pos.bill_no, doc.name, "b") }}
{{ put(pos.farmer_name, doc.farmer_name or "", "b") }}
{{ put(pos.farmer_no, doc.farmer or "", "b") }}
{{ put(pos.bill_date, day(doc.bill_date)) }}
{{ put(pos.period, day(doc.from_date) ~ " TO " ~ day(doc.to_date)) }}
{{ put(pos.village, village) }}

{% for s in doc.slips %}
 {%- set y = rows.first_y + loop.index0 * step -%}
 {%- set gross = s.gross_quantity or ((s.cane_weight or 0) / 1000) -%}
 {{ put([col.date, y], day(s.slip_date), "row") }}
 {{ put([col.vehicle, y], s.vehicle or "", "row") }}
 {{ put([col.slip, y], s.slip or "", "row") }}
 {{ put([col.tonnage, y], "%.3f"|format(gross), "row") }}
 {{ put([col.rate, y], money(s.rate), "row") }}
 {{ amount(y, money((gross * (s.rate or 0))|round(2)), "row") }}
{% endfor %}

{{ put(pos.total_tonnage, "%.3f"|format(t.gross_qty), "b") }}
{{ amount(pos.gross_amount_y, money(t.gross_amt), "b") }}
{{ put(pos.binding_kg, (t.binding_kg|int) ~ " KG") }}
{{ amount(pos.binding_amount_y, money(t.binding_amt)) }}
{{ amount(pos.other_amount_y, money(other_amt)) }}
{{ amount(pos.net_amount_y, money(doc.total_amount), "net") }}

{{ put(pos.slip_farmer, doc.farmer_name or "", "b") }}
{{ put(pos.slip_village, village) }}
{{ put(pos.slip_amount, money(doc.total_amount), "b") }}
{{ put(pos.slip_bill_no, doc.name) }}
{{ put(pos.slip_bill_date, day(doc.bill_date)) }}
{{ put(pos.slip_cash_ref, "") }}
</div></div>
